        int n = Integer.parseInt(br.readLine().trim());
        StringTokenizer st = new StringTokenizer(br.readLine());
        PriorityQueue<Long> low = new PriorityQueue<>(Collections.reverseOrder());
        PriorityQueue<Long> high = new PriorityQueue<>();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            long x = Long.parseLong(st.nextToken());
            if (low.isEmpty() || x <= low.peek()) low.add(x); else high.add(x);
            if (low.size() > high.size() + 1) high.add(low.poll());
            else if (high.size() > low.size()) low.add(high.poll());
            if (i > 0) sb.append(' ');
            sb.append(low.peek());
        }
        System.out.println(sb);
    }
}

